#!/bin/sh
# Build RAChoice 1.5 (CaffeineOS build of flype44's RAChoice 1.2, MPL-2.0) with the
# amiga6 m68k-amigaos-gcc 6.5.0b, libnix.  -fno-peephole2 at every -O level (global
# CLAUDE.md).  -Wno-parentheses: upstream's "if (x = f())" style, kept as is.
# RAChoice.c is generated by port_rachoice.py from upstream-1.2/RAChoice.c; ownreq.c is ours.
# "sh build.sh test" also builds RAChoice.test with the RAChoiceTest switch of ownreq.c (never shipped).
set -e
export TMP='D:\amiga-gcc\tmp'
cd "$(dirname "$0")"
CC=/d/amiga-gcc-amiga6/bin/m68k-amigaos-gcc
FLAGS="-noixemul -m68040 -mtune=68040 -O2 -fno-peephole2 -Wall -Wextra -Wno-unused-parameter -Wno-parentheses"
$CC $FLAGS -o RAChoice RAChoice.c ownreq.c -lamiga
/d/amiga-gcc-amiga6/bin/m68k-amigaos-strip RAChoice
ls -l RAChoice
if [ "$1" = test ]; then
  $CC $FLAGS -DOWNREQ_TEST -o RAChoice.test RAChoice.c ownreq.c -lamiga
  /d/amiga-gcc-amiga6/bin/m68k-amigaos-strip RAChoice.test
  ls -l RAChoice.test
fi
